const row = $input.first().json || {};
const norm = $('Normalizar request').first().json;
let userId = '';
let sessionId = '';
try { const auth = $('Validar auth').first().json; userId = auth.userId || ''; sessionId = auth.sessionId || ''; } catch (_) {}
const hasId = Boolean(row && row.id);
return [{ json: { data: hasId ? row : row, asList: false, statusCode: 201, requestId: norm.requestId, requestStartedAtMs: norm.requestStartedAtMs, method: norm.method, path: norm.path, userId, sessionId } }];

const err = $input.first().json || {};
const msg = String(err.message || err.error?.message || err.description || JSON.stringify(err));
const isDuplicate = /users_email_key|duplicate key.*email|unique constraint.*email/i.test(msg);
const requestId = $('Normalizar request').first().json.requestId;
if (isDuplicate) {
  return [{ json: { code: 'USER_EMAIL_ALREADY_EXISTS', message: 'Já existe um usuário com este e-mail.', statusCode: 409, requestId } }];
}
return [{ json: { code: 'INTERNAL_ERROR', message: 'Ocorreu um erro inesperado.', statusCode: 500, requestId } }];

const prep = $('Preparar sucesso').first().json || {};
const audit = $input.first().json || {};
return [{ json: audit.response != null ? audit : prep }];

const prep = $('Preparar erro 403').first().json || {};
const audit = $input.first().json || {};
return [{ json: audit.response != null ? audit : prep }];

const prep = $('Preparar erro 409').first().json || {};
const audit = $input.first().json || {};
return [{ json: audit.response != null ? audit : prep }];
